CREATE TABLE IF NOT EXISTS jamco_community_users (id uuid PRIMARY KEY,email text UNIQUE NOT NULL,display_name text NOT NULL,password_hash text NOT NULL,location text NOT NULL DEFAULT '',bio text NOT NULL DEFAULT '',interests jsonb NOT NULL DEFAULT '[]',following jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE jamco_community_users ADD COLUMN IF NOT EXISTS verified boolean NOT NULL DEFAULT false;
ALTER TABLE jamco_community_users ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE jamco_community_users ADD COLUMN IF NOT EXISTS avatar text NOT NULL DEFAULT '';
ALTER TABLE jamco_community_users ADD COLUMN IF NOT EXISTS premium_until timestamptz;
ALTER TABLE jamco_community_users ADD COLUMN IF NOT EXISTS preferences jsonb NOT NULL DEFAULT '{"posts":true,"replies":true,"submissions":true,"membership":true}';
CREATE TABLE IF NOT EXISTS jamco_community_sessions (digest text PRIMARY KEY,user_id uuid NOT NULL REFERENCES jamco_community_users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jamco_community_saves (user_id uuid NOT NULL REFERENCES jamco_community_users(id) ON DELETE CASCADE,permalink text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,permalink));
CREATE TABLE IF NOT EXISTS jamco_community_submissions (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jamco_community_users(id),category text NOT NULL,headline text NOT NULL,description text NOT NULL,location text NOT NULL DEFAULT '',media jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'submitted',editorial_note text NOT NULL DEFAULT '',post_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE jamco_staff ADD COLUMN IF NOT EXISTS permissions jsonb NOT NULL DEFAULT '[]';
ALTER TABLE jamco_staff ADD COLUMN IF NOT EXISTS totp_secret text;
ALTER TABLE jamco_staff ADD COLUMN IF NOT EXISTS totp_last bigint NOT NULL DEFAULT -1;
ALTER TABLE jamco_staff ADD COLUMN IF NOT EXISTS pending_totp text;
ALTER TABLE jamco_sessions ADD COLUMN IF NOT EXISTS mfa_ok boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS jamco_social_likes (slug text NOT NULL REFERENCES jamco_content(slug) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES jamco_community_users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(slug,user_id));
CREATE TABLE IF NOT EXISTS jamco_comments (id uuid PRIMARY KEY,slug text NOT NULL REFERENCES jamco_content(slug) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES jamco_community_users(id),parent_id uuid REFERENCES jamco_comments(id),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),edited_at timestamptz);
CREATE INDEX IF NOT EXISTS jamco_comments_thread ON jamco_comments(slug,created_at,id);
CREATE TABLE IF NOT EXISTS jamco_comment_likes (comment_id uuid NOT NULL REFERENCES jamco_comments(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES jamco_community_users(id) ON DELETE CASCADE,PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS jamco_social_reports (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jamco_community_users(id),slug text REFERENCES jamco_content(slug),comment_id uuid REFERENCES jamco_comments(id),reason text NOT NULL,resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jamco_notifications (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jamco_community_users(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,url text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jamco_notifications_member ON jamco_notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS jamco_memberships (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES jamco_community_users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')),expires_at timestamptz,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS jamco_membership_pending ON jamco_memberships(user_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS jamco_verification (digest text PRIMARY KEY,user_id uuid REFERENCES jamco_community_users(id),staff_email text REFERENCES jamco_staff(email),purpose text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS jamco_views (slug text NOT NULL REFERENCES jamco_content(slug) ON DELETE CASCADE,viewer text NOT NULL,day date NOT NULL DEFAULT current_date,PRIMARY KEY(slug,viewer,day));
CREATE INDEX IF NOT EXISTS jamco_scheduled ON jamco_content(live_at) WHERE state='published';
CREATE INDEX IF NOT EXISTS jamco_sessions_expiry ON jamco_community_sessions(expires_at);
CREATE INDEX IF NOT EXISTS jamco_submission_status ON jamco_community_submissions(status,created_at);
CREATE TABLE IF NOT EXISTS jamco_stories (id uuid PRIMARY KEY,post_slug text NOT NULL REFERENCES jamco_content(slug) ON DELETE CASCADE,created_by text NOT NULL REFERENCES jamco_staff(email),media jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jamco_story_expiry ON jamco_stories(expires_at DESC);
